import{_ as i,o as t,c as s,a0 as a}from"./chunks/framework.BtvJJXVw.js";const p=JSON.parse('{"title":"Filesharing","description":"","frontmatter":{"layout":"home","title":"Filesharing","hero":{"name":"Filesharing","text":"Share legal documents without the risk","tagline":"Stop emailing confidential files. Larx gives your firm and your clients one secure place to exchange, organise and track every document in a case.","actions":[{"theme":"brand","text":"Book a demo","link":"/about"},{"theme":"alt","text":"All features","link":"/features"}]}},"headers":[],"relativePath":"filesharing.md","filePath":"filesharing.md"}'),o={name:"filesharing.md"};function n(r,e,l,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[a('<section class="lx-section"><div class="lx-hero-shot">Product screenshot placeholder — filesharing overview</div></section><section class="lx-section"><div class="lx-section-head"><h2>Email was never built for confidential documents</h2><p>Every attachment you send leaves your control the moment it&#39;s sent. For a law firm, that&#39;s a professional risk — and a daily annoyance.</p></div><div class="lx-grid lx-grid--4 lx-why"><div><h4>No control</h4><p>Once a file is emailed, you can&#39;t revoke it, expire it, or know who forwarded it.</p></div><div><h4>Version chaos</h4><p>&quot;Contract_final_v3_DEF(2).docx&quot; — nobody knows which version is the real one.</p></div><div><h4>Size limits</h4><p>Case files, exhibits and scans routinely bounce against mailbox limits.</p></div><div><h4>No overview</h4><p>Documents for one matter end up scattered across dozens of email threads.</p></div></div></section><section class="lx-section"><div class="lx-showcase"><div class="lx-showcase-text"><h3>A secure portal your clients actually use</h3><div class="lx-mini-feature"><h4>Simple for clients</h4><p>Representatives receive an onboarding email, set their own password once, and from then on see exactly their documents and dossiers — no software to install, no manual to read.</p></div><div class="lx-mini-feature"><h4>Your firm&#39;s branding</h4><p>The portal carries your firm&#39;s name and logo, so clients always know who they&#39;re dealing with.</p></div><div class="lx-mini-feature"><h4>Automatic notifications</h4><p>You&#39;re notified the moment a client uploads a document — and clients see when something is waiting for them.</p></div></div><div class="lx-showcase-image">Screenshot placeholder — client portal</div></div><div class="lx-showcase lx-showcase--reverse"><div class="lx-showcase-text"><h3>You decide who sees what, for how long</h3><div class="lx-mini-feature"><h4>Per-document permissions</h4><p>Share a single document or a whole matter folder. Grant view-only or download rights, per person.</p></div><div class="lx-mini-feature"><h4>Expiring links</h4><p>Set an expiry date on anything you share. After that, access simply stops — no chasing required.</p></div><div class="lx-mini-feature"><h4>Revoke at any time</h4><p>Shared something by mistake, or a matter has closed? Withdraw access with one click.</p></div></div><div class="lx-showcase-image">Screenshot placeholder — permissions</div></div><div class="lx-showcase"><div class="lx-showcase-text"><h3>Every document in its place, automatically</h3><div class="lx-mini-feature"><h4>Organised by matter</h4><p>Files live inside the case they belong to — together with the notes, tasks and correspondence of that matter.</p></div><div class="lx-mini-feature"><h4>Version history</h4><p>Larx keeps every version of a document. Compare, restore or refer back — the current version is always unmistakable.</p></div><div class="lx-mini-feature"><h4>Fast full-text search</h4><p>Find any document by name, client, matter or content — in seconds, not minutes.</p></div></div><div class="lx-showcase-image">Screenshot placeholder — matter files</div></div></section><section class="lx-section"><div class="lx-section-head"><h2>Security a law firm can stand behind</h2><p>Confidentiality isn&#39;t a feature for a law firm — it&#39;s an obligation. Larx is built to meet it.</p></div><div class="lx-grid lx-grid--4 lx-why"><div><h4>Encrypted end to end</h4><p>Documents are encrypted in transit and at rest. Nobody outside your firm and your client can read them.</p></div><div><h4>EU data residency</h4><p>All data is stored on servers within the European Union, fully GDPR compliant.</p></div><div><h4>Complete audit trail</h4><p>Every view, download and share is logged — so you can always demonstrate who accessed what, and when.</p></div><div><h4>Two-factor access</h4><p>Portal access is protected with two-factor verification, for your team and your clients alike.</p></div></div></section><section class="lx-section"><div class="lx-section-head"><h2>Up and running in minutes</h2></div><div class="lx-steps"><div class="lx-step"><h4>Create a matter</h4><p>Add the case and drop in the documents that belong to it — drag and drop, straight from your desktop.</p></div><div class="lx-step"><h4>Invite your client</h4><p>Send a secure invitation. Your client gets access to exactly the documents you choose — nothing more.</p></div><div class="lx-step"><h4>Share and track</h4><p>Exchange documents both ways and follow everything in the audit trail. No more attachment ping-pong.</p></div></div></section><section class="lx-section"><div class="lx-section-head"><h2>Frequently asked questions</h2></div><div class="lx-faq"><details><summary>How do my clients get access?</summary><p>Your firm creates the account: the representative receives an onboarding email, clicks the link, sets a personal password — and immediately sees their own environment with exactly the dossiers they&#39;ve been given access to. Nothing to install, nothing to configure.</p></details><details><summary>Is there a limit on file size or storage?</summary><p>Larx handles large case files, scans and media without the size limits of email. Storage depends on your plan — see pricing for details.</p></details><details><summary>Where is my data stored?</summary><p>All documents are stored encrypted on servers within the European Union, in line with GDPR requirements for legal professionals.</p></details><details><summary>Can I migrate documents from my current system?</summary><p>Yes. You can upload existing folders in bulk, and we help you map them onto clients and matters during onboarding.</p></details><details><summary>What happens when a matter is closed?</summary><p>You can archive the matter: client access ends automatically, while your firm keeps the complete file and audit trail for its retention period.</p></details></div></section><section class="lx-section"><div class="lx-banner lx-cta"><div class="lx-banner-text"><h3>Ready to retire the email attachment?</h3><ul class="lx-checklist"><li>✓ Free personal demo, no strings attached</li><li>✓ Set up in one afternoon</li><li>✓ No credit card required</li></ul><a class="lx-button" href="/about">Book a demo</a></div><div class="lx-banner-image">Screenshot placeholder</div></div></section>',7)])])}const u=i(o,[["render",n]]);export{p as __pageData,u as default};
